/* * char ** arglist( char * , code ) * * convert command string to argument array format * * code=separator * code=0 -> separate on space, throw out multiple, handle quotes*/#define ERR (-1)#include <errno.h>int os9forkc();extern char **environ;char **malloc();char **arglist(s,c)char *s;int c;{	char **ppcArgs;	char **ppcTemp;	int iArgs;	iArgs=16;	ppcArgs=malloc(iArgs*4+4);	if (!ppcArgs)		return(0);	ppcTemp=ppcArgs;	*ppcTemp++=s;	while (*s)	{		if (c)		{			while (*s && *s!=c)				s++;			if (*s)				*s++=0;		}		else		{			while (*s && *s!=' ')			{				if (*s==34)				{					strcpy(s,s+1);					while (*s && *s!=34)						s++;					if (*s)						strcpy(s,s+1);				}				else					s++;			}			while (*s && *s==' ')				*s++=0;		}		if (*s)		{			if (ppcTemp-ppcArgs>=iArgs*4)			{				ppcTemp=malloc(iArgs+4+4*8+4);				if (!ppcArgs)					return(0);				memcpy(ppcTemp,ppcArgs,iArgs*4);				free(ppcArgs);				ppcArgs=ppcTemp;				ppcTemp+=iArgs;			}			*ppcTemp++=s;		}	}	*ppcTemp=0;	return(ppcArgs);}fork(pcCmd)char *pcCmd;{	int iPid;	int iWait;	char **ppcArgs;	ppcArgs=arglist(pcCmd,0);	if (*pcCmd=='-')		pcCmd++;	iPid=os9exec(os9forkc,pcCmd,ppcArgs,environ,0,0,3);	if (iPid==ERR)		return(ERR);	while (1)	{		iWait=wait(&errno);		if (iWait==ERR)			return(ERR);		if (iWait==iPid)			break;	}	if (errno)		return(ERR);	return(0);}